        start = divider_rows[i - 1] + 1
        end = divider_rows[i] - 1
        if start <= end:
            regions.append((start, end, end - start + 1))

    if divider_rows and divider_rows[-1] < len(grid) - 1:
        last_div = divider_rows[-1]
        regions.append((last_div + 1, len(grid) - 1, len(grid) - 1 - last_div))

    # Swap row regions: first <-> last, second <-> second-to-last
    result = [row[:] for row in grid]

    for i in range(len(regions) // 2):
        j = len(regions) - 1 - i
        if i >= j:
