"""Transform function for task-45984eee: flips row regions 1-4 vertically (skips region 0)"""

def find_divider_rows(grid, divider_val=8):
    """Find rows that are completely filled with divider value"""
    divider_rows = []
    for i, row in enumerate(grid):
        if sum(1 for c in row if c != divider_val) <= 0.1 * len(row):
            divider_rows.append(i)
    return divider_rows

def flip_row_regions_skip_first(grid, divider_val=8):
    """Flip row regions 1-4 vertically, skipping region 0"""
    divider_rows = find_divider_rows(grid, divider_val)

    result = [row[:] for row in grid]

    # Build regions
    regions = []
    if divider_rows:
        regions.append((0, divider_rows[0] - 1))  # region 0
    for i in range(1, len(divider_rows)):
        regions.append((divider_rows[i - 1] + 1, divider_rows[i] - 1))
    if divider_rows and divider_rows[-1] < len(grid) - 1:
        regions.append((divider_rows[-1] + 1, len(grid) - 1))  # last region

    # Flip regions 1, 2, 3, 4 (skip region 0)
    for i in range(1, len(regions)):
        s, e = regions[i]
        h = e - s + 1
        for col in range(len(grid[0])):
            for row_off in range(h // 2):
                result[s + row_off][col], result[s + (h - 1 - row_off)][col] = \
                    result[s + (h - 1 - row_off)][col], result[s + row_off][col]

    return result

def transform(grid):
    return flip_row_regions_skip_first(grid, 8)
